import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_token(token):
    """Verify HMAC-based API token: base64(user_id):hmac_hex"""
    if not token or ':' not in token:
        return None
    parts = token.split(':', 1)
    user_id = parts[0]
    provided_mac = parts[1]
    expected_mac = hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(provided_mac, expected_mac):
        return user_id
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by name or email. Requires valid API token."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_api_token(auth[7:])
    if caller is None:
        return jsonify({'error': 'invalid token'}), 403

    query_param = request.args.get('q', '')
    field = request.args.get('field', 'name')

    # Input validation - only allow searching specific fields
    allowed_fields = ['name', 'email', 'department', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build query with parameterized field but concatenated search value
    # Note: field is validated above against allowlist
    sql = f"SELECT id, name, email, department, role FROM users WHERE {field} LIKE '%{query_param}%'"

    try:
        db = get_db()
        cursor = db.execute(sql)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_api_token(auth[7:])
    if caller is None:
        return jsonify({'error': 'invalid token'}), 403

    db = get_db()
    cursor = db.execute('SELECT id, name, email, department, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user. Admin only."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_api_token(auth[7:])
    if caller is None:
        return jsonify({'error': 'invalid token'}), 403

    data = request.get_json()
    if not data:
        return jsonify({'error': 'no data'}), 400

    name = data.get('name', '')
    email = data.get('email', '')
    department = data.get('department', '')
    role = data.get('role', 'viewer')

    db = get_db()
    db.execute(
        'INSERT INTO users (name, email, department, role) VALUES (?, ?, ?, ?)',
        (name, email, department, role)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

